    var mo = tel.match(/tel=([^,}\s]+)/);
    tel = mo ? mo[1] : "";
  }
  if (pwd.indexOf("pwd=") >= 0 || pwd.indexOf("{") === 0) {
    var mp = pwd.match(/pwd=([^,}\s]+)/);
    pwd = mp ? mp[1] : "";
  }
  if (!tel || !pwd || tel == "null" || pwd == "null" || tel.indexOf("tel=") >= 0 || pwd.indexOf("pwd=") >= 0) {
    T9_T(java, "请先在登录界面的「手机号」「密码」框里填写，再点登录"); return;
  }
