  try {
    var t0 = Date.now();
    var CK = T9_SCOOKIE();
    var HD = { "User-Agent": T9_UA };
    if (CK) HD["Cookie"] = CK;
    var hex = String(java.ajax(T9_SOSO + "?action=captcha_api&t=" + t0 + "," + JSON.stringify({ "type": "hex", "headers": HD })));
