    var bytes = java.hexDecodeToByteArray(hex);
    var b64 = String(Packages.android.util.Base64.encodeToString(bytes, 2));
    var dataUri = "data:image/png;base64," + b64;
    cap = String(java.getVerificationCode(dataUri));
  } catch (e) { T9_T(java, "获取验证码失败:" + e); return; }
  if (!cap || cap == "null" || cap.length < 3) { T9_T(java, "未取到验证码，请重试"); return; }
  var CK2 = T9_SCOOKIE();
  var HD2 = { "User-Agent": T9_UA, "Content-Type": "application/x-www-form-urlencoded",
              "Referer": T9_SOSO + "?action=login", "X-Requested-With": "XMLHttpRequest" };
  if (CK2) HD2["Cookie"] = CK2;
  var opt = { method: "POST",
    body: "mobile=" + java.encodeURI(tel) + "&password=" + java.encodeURI(pwd) + "&captcha=" + java.encodeURI(cap),
    headers: HD2 };
  var r = "", tries = 0;
  while (tries < 3) {
    tries++;
    try { r = String(java.ajax(T9_SOSO + "?action=user_api&act=login," + JSON.stringify(opt))); } catch (e) { r = ""; }
    if (r.indexOf("code") >= 0) break;
    try { Packages.java.lang.Thread.sleep(1200); } catch (e2) {}
  }
  if (r.indexOf("code") < 0) { T9_T(java, "登录请求失败：连不上 soshu 网关（已重试3次）"); return; }
