  var c = T9_code(r), msg = T9_msg(r);
  if (c === 0) { T9_T(java, "登录成功（搜索额度已恢复）" + (msg ? "：" + msg : "")); }
  else if (c === -1) { T9_T(java, "登录失败：" + (msg || "手机号或密码错误") + "，若刚刷新过验证码请再试一次"); }
  else if (c !== null) { T9_T(java, "登录失败(" + c + ")：" + (msg || r.substring(0, 60))); }
  else { T9_T(java, "登录失败：响应无法解析 " + r.substring(0, 60)); }
}
function T9_check() {
  var r = "";
  try { var CKc=T9_SCOOKIE(); var HHc=CKc?{"User-Agent":T9_UA,"Cookie":CKc}:{"User-Agent":T9_UA}; r = String(java.ajax(T9_SOSO + "?action=user_api&act=me," + JSON.stringify({headers:HHc}))); } catch (e) { T9_T(java, "检查失败:网络错误"); return; }
  var c = T9_code(r);
  if (c === 0 && r.indexOf("\"data\":null") < 0) {
    var nm = r.match(/"name":"([^"]*)"/);
    T9_T(java, "已登录：" + (nm ? T9_U(nm[1]) : "账号"));
  } else if (c === 0) { T9_T(java, "未登录，请点「登录搜搜书」"); }
  else { T9_T(java, "检查失败(" + (c === null ? "?" : c) + ")"); }
}
function T9_quota() {
  var r = "";
  try { var CKq=T9_SCOOKIE(); var HHq=CKq?{"User-Agent":T9_UA,"Cookie":CKq}:{"User-Agent":T9_UA}; r = String(java.ajax(T9_SOSO + "?s=x&web=m159txt," + JSON.stringify({headers:HHq}))); } catch (e) { T9_T(java, "检查失败:网络错误"); return; }
